# Q14 round 2: replaces Q14g/Q14h, appends Q14i-Q14m, annotates Q14a/c/d, updates recipe/caveats/interpretation (idempotent). python3 build_report_q14b.py
import json
p='/output/report.json'; r=json.load(open(p))
NEW=('Q14i','Q14j','Q14k','Q14l','Q14m')
r['results']=[x for x in r['results'] if not x['quantity'].startswith(NEW) and not x['quantity'].startswith('Q14g') and not x['quantity'].startswith('Q14h')]
r['recipe']=[x for x in r['recipe'] if not x['description'].startswith('Q14 round 2')]
r['caveats']=[x for x in r['caveats'] if not x.startswith('Q14 round 2')]
i=r['interpretation'].find('\n\nQ14:'); r['interpretation']=r['interpretation'][:i] if i>=0 else r['interpretation']
A=lambda n,v:{"name":n,"value":v}
common=[A("regions","out/regions.csv: N (0,+2.55\"), S (-0.15,-2.55\"), Bridge (+0.30,+0.15\"), Wclump (-1.8,-2.4\"), Soutflow (-0.15,-4.5\"); values at the position (bilinear) of cubes convolved channel-wise to the stated beam"),
 A("intensity","K km/s = Rayleigh-Jeans Tb, pbcor cubes; line-shape template = HCO+ spectrum of the same pixel/beam; baseline linear; errors = residual rms (robust) x1.3 (channel correlation, assumption) and empirical nulls where stated"),
 A("redshift","rest frequencies at vsys 2775-2780 km/s (radio); CDMS/JPL/LAMDA frequencies")]
def R(q,v,u,unit,conf,ev,tgt,extra=()):
    r['results'].append({"quantity":q,"value":v,"uncertainty":u,"unit":unit,"confidence":conf,"evidence":ev,"target":tgt,"assumptions":common+list(extra)})
# ---- annotate older entries
for x in r['results']:
    q=x['quantity']
    if q.startswith('Q14a') and '[Q14i' not in x['value']:
        x['value']+=" [Q14i supersedes the S-N significance: with whole-line template amplitudes and an empirical off-source null, S-N = 2.8-3.0 sigma per array at 6.3x3.8\" and <=1.5 sigma at <=4.45\"; the fixed-position CH3OH peak lies 1-3\" from N and S towards the Bridge/W clump.]"
    if q.startswith('Q14c') and '[Q14k' not in x['value']:
        x['value']+=" [Q14k: the Trot of this entry is a thin-LTE Tex; RADEX reproduces R(254/blend)=0.31 at S with n~10^5.5-10^6.5 cm-3 (Tk 20-100 K) and Tex(254) = 5-7 K, i.e. the 254 line is sub-thermal there: N(CH3OH) is then 1.7-4.9x (vs LTE 10 K) larger.]"
    if q.startswith('Q14d') and '[Q14k' not in x['value']:
        x['value']+=" [Q14k/Q14m: non-LTE (RADEX) N(A+E) at S = 1.8-5.0e14 cm-2 vs LTE 1.0-2.3e14 (10-30 K); abundances relative to N(H2) from dust in Q14m; the tau-corrected HCO+ route here is superseded by Q14m.]"
common_h=[A("Harada paper","N. Harada et al. 2018, ApJ 855, 49 (arXiv:1801.05941): Table 1 (arrays), Table 2 (beams), Table 3, Table 13 (K km/s at 1.7\" integrated +-150 km/s about 2775 km/s) read from lit/harada/harada.txt")]
# ---- Q14g
R("Q14g: matched comparison with Harada+2018 (CH3OH 2k-1k 96.74 GHz / HCO+ 3-2 at 1.7\"): data facts, matched-estimator prediction and which explanation is allowed",
"HARADA SETUP (paper, Table 1-3): CH3OH 96.74 comes from Band3_c (94.7-98.3 GHz) 12-m ONLY (PI data 2015.1.00412.S/2016.1.00965.S C36-2/3, baselines 14.6-628 m, plus archive 2015.1.00993.S C36-2/3, 13.6-428 m; no ACA at Band 3; the earlier statement 'ACA-including Band 3' was wrong), imaged 1.68x1.62\" (rob1, rms 17.9 mJy/beam km/s); HCO+ 3-2 is 12-m C36-2/3 (13.7-412 m) + 7-m ACA (9-44.5 m), 0.94x0.90\"; all spectra convolved to 1.7\" circular, integral = sum over +-150 km/s about 2775 km/s with no baseline fit (error dI dv sqrt(N), N for 300 km/s); Table 13 values: CH3OH 2k-1k N 3.09+-0.66, S 6.22+-0.66 K km/s; HCO+ 3-2 N 91.56, S 43.69 (our Xb4d at 1.7\", +-150 km/s: N 86.0, S 53.7: -6%, +23%); 241.79 5k-4k N 5.84+-0.57, S 4.35+-0.57; 254.015 is not in Table 13 at N/S (<2 sigma peak). Shortest 12-m baselines 13.6-14.6 m at 96.7 GHz give MRS ~0.6 lambda/B = 28\" (ours at 254 GHz: Xb4d min baseline not in headers; Xb4f beam 6.3x3.8\" at 265 GHz implies B_max~45 m, i.e. a compact/ACA-like array, inferred not verified). "
"OUR ESTIMATOR LADDER at S, 1.7\" (K km/s of 254.015): window moment (+-150 km/s, local baseline) 0.447+-0.17 (empirical null 0.16-0.28) -> whole-line HCO+-template fit with SiS 14-13 and 30SiO 6-5 in the same window 0.694 (S/N 2.6) -> + feathering with the low-resolution deficit D=[Xb4f-Xb4d] at 6.3x3.8\" (+0.19+-0.11 S, +0.03 N) 0.877+-0.285; N: 0.226 -> 0.370+-0.24 -> 0.396+-0.26. The +-150 km/s window contains 97% (S) / 99% (N) of the line. "
"PREDICTED 96.74 (K km/s; LTE at Harada's OWN Trot from 241.79/96.74 = 0.70 (S) -> 11.1 (10.4-11.8) K, 1.89 (N) -> 17.3 (15.5-19.9) K; R96/254 = 5.96 (S), 5.36 (N), CMB contrast included): S Xb4d-only 4.14+-1.59 (0.67 of Harada, -1.2 sigma), feathered 5.23+-1.70 (0.84, -0.5 sigma; to Harada's HCO+ 0.120 vs 0.142+-0.015); N Xb4d-only 1.98+-1.29 (0.64), feathered 2.12+-1.39 (0.69, -0.6 sigma; ratio 0.023 vs 0.034+-0.007). Using R96/254 = 4.9-6.6 (Trot 8-30 K) changes this by <=15%. Non-LTE (RADEX constrained by R(254/Q-blend) and Harada's 241.79/96.74): N R96/254 = 8.6 (7.5-12) -> pred 3.2-3.4 (1.0-1.1 of Harada, +0.1 sigma); S R96/254 = 23 (20-27) -> pred 15-23 (2.5-3.6x Harada, +1.5-2.2 sigma; this S solution is itself a poor joint fit, chi2=8.9 for the 2 ratios, which refer to different beams). "
"VERDICT: the previous 'x3 tension' (pred 0.04-0.05 vs 0.142 at 1.7\") came from the window-limited moment at 1.7\" with a +-50% error; with the matched whole-line estimator the LTE prediction agrees with Harada within ~1 sigma at both nuclei (pred/Harada 0.64-0.84). Which of the three explanations is allowed: (1) uv coverage - allowed and measured but not dominant: feathering adds +26% (S) / +7% (N); the 12-m data recover 98+-16% (R<=3\") to 64+-10% (R=6\") of Xb4f CH3OH flux at S (Q14j); (2) aperture/position - not required; shifting the 1.7\" aperture by <=0.5\"/1\" changes the feathered S 254 to 0.86/1.13 K km/s (window estimator), i.e. a <=1\" pointing difference can by itself supply the residual 20%; (3) excitation - LTE at Harada's own Trot suffices; high-density non-LTE solutions would overshoot at S by 2.5-3.6x and are mildly (1.5-2 sigma) disfavoured, low-density ones undershoot. The data cannot separate the three at the +-30% error of the 254 line; none is needed to reproduce Harada.",
"+-30% on our 254 intensity at 1.7\" (S: 0.69+-0.27 K km/s whole line) and +-10% (Harada, Table 13 errors) -> pred/Harada 0.84+-0.28 (S feathered), 0.69+-0.46 (N feathered); +-15% conversion (Trot 8-30 K); factor 0.9 (CMB contrast on/off, Q14k)","ratio","medium",
"scripts/q14f_harada.py, q14h_deblend.py, q14l_harada_final.py -> out/q14f/*.csv, out/q14e/deblend_all.csv, harada_final.csv, radex_posterior_{N,S}.csv; lit/harada/harada.txt (Tables 1-3, 13)","N, S",common_h+[A("conversion","N_A=N_E=N/2, each ladder on its own LAMDA partition sum, CMB contrast on (Q14k); 96.74 group = 3 E lines + 1 A line within 96.73-96.76 GHz; 254 = E-line 2(0)-1(-1)"),A("feather","I(1.7\")_feather = I_Xb4d(1.7\") + [I_Xb4f - I_Xb4d] at 6.3x3.8\" (assumes the deficit is smooth on 1.7\" scales and Xb4f complete)")])
# ---- Q14i
R("Q14i: robust S>N test of CH3OH 254 / HCO+ 3-2 (whole-line template amplitudes, empirical off-source null) and CH3OH peak positions",
"Whole-line CH3OH amplitude (K km/s) / HCO+ 3-2 (Gaussian integral) at N and S: Xb4d 6.3x3.8\": N 0.121+-0.050 / 22.8 = 0.0053, S 0.381+-0.057 / 17.2 = 0.0222; S-N = 0.0169+-0.0059 (2.9 sigma; 3.0 sigma vs 80 random off-source position pairs 9-16\" from the centre); Xb4f 6.3x3.8\": N 0.147+-0.082 (1.2 sigma vs null), S 0.569+-0.090 (4.6 sigma): 0.0056 / 0.0254, S-N = 0.0199+-0.0072 (2.8 sigma; 3.0 ring-pair); Xb4d 4.45x2.95\": 1.5 sigma (0.0061 / 0.0207); 3.0\": 1.2 sigma; 1.7\": 0.7 sigma (S/N ratio of the two ratios 2.7-4.6 at all beams, but errors at <=4.45\" are large). The fixed-window moment estimator with the paired shifted-window null (q14g_ns.py) gives 2.2 sigma (Xb4d FWHM window) - 3.0 sigma (Harada window) at 6.3x3.8\" and 2.6-2.7 sigma (Xb4f); the shifted-window and ring nulls agree within 20%. The null mean (off-source amplitude) is -0.05 to -0.07 K km/s (template baseline), common to N and S. S alone is a 4.6 sigma detection at 6.3\" (Xb4d and Xb4f); N is 1.2-1.6 sigma (upper limit <0.39 K km/s 3 sigma in Xb4f). CH3OH PEAK within 3.5\" of the region (moment-0 over the HCO+ FWHM window; offsets E,N in arcsec): at 1.7\" N -> (+0.15,-2.40) and S -> (+0.30,+2.70), i.e. both nuclear pixels sit on the slope of the Bridge/W-clump emission (Bridge (0.0,+0.15), W clump (-0.3,+0.15), 1.0-1.2 K km/s at 1.7\"); at 6.3x3.8\" Xb4f: N (-0.7,-3.25), S (-1.95,+0.45), Bridge (-2.4,-2.25), Wclump (-0.3,+0.3), Soutflow (-1.95,+1.7). VERDICT: S>N CH3OH/HCO+ is MODERATE (2.8-3.0 sigma per array at the one beam where both arrays are usable; ~4 sigma only if the two arrays are treated as independent; <1.5 sigma at <=4.45\"), the value is dominated by extended Bridge/W-clump-linked emission, not an S-nuclear source.",
"S-N error 0.006-0.007 (empirical, = max(null rms, fit error x1.3)); systematic: template shape (+-10%), baseline (null mean -0.05 K km/s), Xb4d vs Xb4f recovery (Q14j)","ratio","medium",
"scripts/q14e_m0.py, q14g_ns.py, q14m_ns_deblend.py -> out/q14e/m0_table.csv, ns_contrast.csv, ns_deblend.csv, ring.csv","N, S, Bridge, Wclump, Soutflow",[A("null","(a) same estimator in 16 shifted line-free windows of the same spw at the same pixels (moment version), (b) 80 random off-source position pairs 9-16\" from the N-S midpoint (template version); significance = dR / rms(null)")])
# ---- Q14j
R("Q14j: spatial extent of CH3OH 254 from aperture flux recovery (native Xb4d 12-m vs Xb4f compact array) and the uv-coverage test",
"CH3OH 254.015 flux (Jy km/s, +-150 km/s about 2775, per-pixel linear baseline, circular aperture of radius R, noise = rms of 6 shifted line-free windows) centred on S: R=1.5\" Xb4d 0.155 / Xb4f 0.156 (recovery 0.99+-0.32); 3\" 0.529+-0.04 / 0.541+-0.08 (0.98+-0.16); 4.5\" 0.687 / 0.933 (0.74+-0.17); 6\" 0.739+-0.08 / 1.151+-0.12 (0.64+-0.10); 9\" -0.45+-0.2 / 0.91+-0.18 (Xb4d negative: resolved-out bowl); 12\" -1.8 / 0.28. N-S midpoint: 0.22/0.12, 0.52/0.43, 0.76/0.79, 0.64/1.04 (0.62+-0.22 at 6\"), 9\": -0.08 / 0.95. At N the aperture flux (Xb4d/Xb4f) is 0.08/0.06 (1.5\"), 0.27/0.19 (3\"), 0.34/0.57 (6\"), -0.34/0.84 (9\") Jy km/s: weak inside 4.5\" (Xb4d <=2.5 sigma) and the 6-9\" Xb4f flux (~1 Jy km/s for all three centres) is the same extended emission that also falls in the S and Bridge apertures. Across the three centres the Xb4f flux plateaus at ~0.9-1.2 Jy km/s for R=6-9\". HCO+ 3-2 for comparison (Xb4d/Xb4f, S/N/midpoint): 1.06/1.24/1.30 (3\"), 0.82/0.83/1.04 (4.5\"), 0.83-0.88 (6\"), 0.57/0.67/0.62 (9\"), 0.46-0.51 (12\"). So CH3OH is extended (Xb4f flux still rising to R=6\" ~ 1 kpc, the same size as the 6.3x3.8\" beam) and the 12-m data lose >=36% at R=6\" and everything beyond ~9\" (negative bowl), i.e. the extended CH3OH component lies mostly at scales the 12-m data cannot keep; Xb4f itself is limited to its own unknown short-spacing coverage (Harada's 12-m Band-3 data, MRS ~28\", would see more). The 1.7\" Xb4d value is therefore a lower limit on what a complete 1.7\" beam sees: feathering adds +0.19+-0.11 (S) and +0.03 (N) K km/s (Q14g).",
"+-10-30% (aperture noise, N/S); recovery ratios +-0.1-0.3","Jy km/s","medium",
"scripts/q14o_aperture.py, q14f_harada.py -> out/q14e/aperture_recovery.csv, out/q14f/aperture_recovery.csv","S, N, N-S midpoint",[A("apertures","hard circular apertures at native resolution, flux = sum(pix)/beam area; no deconvolution")])
# ---- Q14k
R("Q14k: conversion conventions (96.74/254, 241.79/96.74) and non-LTE (RADEX) bracket for CH3OH",
"CONVENTION (q14f_harada.py, lte_ratios.csv): thin LTE from LAMDA e-ch3oh.dat + ch3oh_a.dat; N_A=N_E=N_tot/2, each ladder normalised on its own Q(T) (E and A partition sums, 2k-1k lines: E 96.739358, 96.744545, 96.755501 + A 96.741371; 254.015377 E; 5k-4k group = E 241.700-241.905 and A 241.791-241.888 sums); W in K km/s per cm-2 with CMB contrast factor (1-(e^x-1)/(e^xb-1)). R96/254 = 12.5, 9.7, 8.3, 7.5, 6.57, 6.09, 5.49, 5.20, 4.89, 4.64 at Tex 3, 4, 5, 6, 8, 10, 15, 20, 30, 50 K; WITHOUT the CMB factor 24, 14.6, 11.1, 9.3, 7.63, 6.82, 5.89, 5.46, 5.05, 4.73: the reviewer's 7.6/6.8/5.9/5.5/5.0/4.7 are exactly the no-CMB column; the CMB-on convention (appropriate for continuum-subtracted data) is 2-14% lower for Tex 8-50 K (11% at 10 K, 14% at 8 K, 25% at 5 K, 1% at 100 K); R241/96 = 0.26, 0.53, 1.43, 2.47, 4.5, 7.8 at 8, 10, 15, 20, 30, 50 K. NON-LTE (q14k_radex.py, p-H2 collider of Rabli & Flower, Tbg 2.73 K, FWHM 150 km/s, equal E,A columns, beam filling 1): with I(254)=0.57 K km/s (S, Xb4f 6.3x3.8\") the 254 line is sub-thermal (Tex 3-11 K, tau<0.1) and: R(254/Q-blend) at Tk=20 K = 9.6, 4.1, 0.70, 0.30, 0.20 for log n = 3.5, 4, 5, 6, 7 (Tk 30-100 K within ~+-30% for n>=10^5); the observed 0.31 (0.22-0.37, q14c) needs n=10^5.5-10^6.5 cm-3 (any Tk 20-100 K); there R96/254 = 9-23 (vs 5-6 in LTE), R241/96 = 1.1-6.2, N_tot(A+E) = 10^14.26-10^14.70 = 1.8-5.0e14 cm-2 (thin: N = 3.2-8.8e14 per K km/s of 254; LTE 1.8, 2.7, 4.0e14 per K km/s at 10, 20, 30 K): non-LTE columns are 1.7-4.9x the LTE(10 K) and 0.8-2.2x the LTE(30 K) values; combined with Harada's S 241.79/96.74 = 0.70 the best (Tk,n) is Tk 20-24 K, n=10^5.2-10^5.5 (R96/254 = 23, N 10^14.5) but with chi2 8.9 (2 ratios; beams differ), at N n=10^6.1-7 (R96/254 7.5-12, N=10^13.7). Tex(CH3OH)~10-11 K from one thin-LTE pair is therefore a sub-thermal Tex (non-LTE), not Tk; Tk is unconstrained (20-100 K).",
"conversion +-12% (CMB convention); LTE vs non-LTE: R96/254 factor 1-4, N factor 1.7-4.9","ratio / cm-2","low",
"scripts/q14f_harada.py, q14k_radex.py, q14l_harada_final.py -> out/q14f/lte_ratios.csv, out/q14e/radex_ch3oh_grid.csv, radex_ch3oh_solutions.csv, radex_posterior_{N,S}.csv","S, N",[A("RADEX","LAMDA e-ch3oh.dat/ch3oh_a.dat have only p-H2 collision rates (Rabli & Flower 2010); o-H2 not included (an assumption: H2 ortho/para ~ thermal at 20-100 K gives a few-10% difference)")])
# ---- Q14l
R("Q14l: SiO (29SiO 8-7, 30SiO 6-5) and SO limits and how informative they are against Harada's SiO",
"Rest frequencies (CDMS/JPL via out/splatalogue_raw.csv): 29SiO 8-7 342.98084 GHz (Eu 74 K, logA -2.67), 30SiO 6-5 254.21666 GHz (Eu 42.7 K, logA -3.07; NOT 254.76 as quoted in the review: the CH2NH 254.685/HC3N 254.70 feature is 570 km/s away); in sky frame 339.805 and 251.863 GHz. Template deblend (HCO+ profile; common v0, width): cluster 254: CH3OH (v0) + SiS 14-13 254.103 (+104 km/s) + 30SiO (+237 km/s); cluster 342.9: CS 7-6 + H2CS 10(0,10)-9(0,9) 342.946 (+56 km/s relative to CS) + 29SiO (+85 km/s; only 29 km/s from H2CS: correlation -0.8 to -0.95). RESULTS (K km/s, 6.3x3.8\"; no detection): 30SiO 6-5 N -0.00+-0.06 (Xb4d) / -0.05+-0.09 (Xb4f), S +0.11+-0.07 / -0.11+-0.10, Bridge 0.03+-0.05 / -0.05+-0.10, Wclump 0.07+-0.06 / -0.09+-0.08, lobe 0.14+-0.07 / -0.04+-0.12 (3 sigma < 0.17-0.36); SiS 14-13 <0.15-0.3 (the 7 sigma 'SiS 14-13' in the Q0 table is CH3OH wing: with CH3OH+SiS+30SiO fitted jointly SiS is -0.14..+0.03+-0.05-0.1); 29SiO 8-7: joint (CS+H2CS+29SiO) N 0.08+-0.12, S -0.01+-0.16, Bridge 0.02+-0.16, lobe 0.16+-0.16 (3 sigma < 0.44, 0.47, 0.51, 0.65); with H2CS fixed to 0: N -0.02+-0.07, S -0.01+-0.07 (3 sigma < 0.20, 0.20, 0.16 Bridge, 0.29 lobe); CS 7-6 (deblended) N 1.13+-0.08, S 0.42+-0.10, Bridge 0.58+-0.10, W 0.31+-0.07, lobe 0.21+-0.10; H2CS 10(0,10) (29SiO=0) <0.23 (N), <0.25 (S) 3 sigma. COLUMNS (thin LTE, rigid rotor validated to 0.1% against LAMDA for CS 7-6, CMB contrast on): N(SiO)/N(CS) 3 sigma upper limits, 28Si/29Si=20 (15-30), 28Si/30Si=30 (25-35): from 29SiO (H2CS=0 / joint) at Tex 20 K: N 2.1 / 4.6, S 5.7 / 13.5, Bridge 3.3 / 10.6; at Tex 10-50 K: N 1.6-3.1 (H2CS=0) / 3.6-7.0 (joint), S 4.4-8.6 / 10.6-20; from 30SiO 6-5 (Xb4d) at Tex 10-50 K: N 0.33-2.1, S 1.6-10, Bridge 0.7-4.7. HARADA's SiO 2-1 / CS 2-1 column ratio (Table 13, 1.7\", Tex 10-30 K): N 0.062+-0.009, S 0.057+-0.020, centre 0.084, TSW 0.12, OS (outflow S) 0.176+-0.046, SW 0.07. INFORMATIVENESS: if N(SiO)/N(CS) equalled Harada's at N/S the predicted line intensities are 29SiO 8-7 0.004-0.008 (N), 0.001-0.003 (S) K km/s and 30SiO 6-5 0.005-0.032 (N), 0.002-0.011 (S) K km/s, i.e. 0.01-0.6 sigma of our noise (0.06-0.16): our 3 sigma limits lie 5-360x above Harada's ratio (30SiO N Tex 10 K 5-9x; 29SiO H2CS=0 N 26-50x; S 80-150x; joint fit 60-360x). The SiO test is NOT informative (we cannot confirm or exclude SiO enhancement at the outflow position) - it would need ~10-20x deeper data. SO 8_8-7_7 (344.31 GHz, Eu 87.5 K) 3 sigma at 6.3x3.8\": I < 0.27 (N), 0.25 (S), 0.15 (Bridge) K km/s -> N(SO) < 2.3e13 (N), 2.2e13 (S) at Tex 20 K (0.5-0.9e13 at 30 K), N(SO)/N(CS) < 1.5-2.4 (N), 3.9-6.2 (S), 1.7-2.7 (Bridge): uninformative (Harada's SO 2(1)-1(2)/CS ~0.1-0.27).",
"3 sigma limits; isotope ratio range 15-30 (29Si), 25-35 (30Si) gives +-25-50%; template shape +-20%; 29SiO-H2CS degeneracy factor ~2.3 in limit","K km/s / ratio","medium",
"scripts/q14h_deblend.py, q14i_abund.py, q14n_summary.py, q14p_so.py -> out/q14e/deblend_all.csv, abund_intensities.csv, abund_sio_cs.csv, abund_sio30_cs.csv, harada_sio_cs.csv, summary_SiO.csv, summary_SO.csv","N, S, Bridge, Wclump, Soutflow",[A("isotopes","28Si/29Si=20 (15-30), 28Si/30Si=30 (25-35): assumed (solar-like; not measured here)"),A("Tex","common Tex 10-50 K for SiO, CS (assumption; Q12/Q2 ranges); SiO/CS limits depend weakly on Tex because Eu(29SiO 8-7)=74 K vs Eu(CS 7-6)=66 K")])
# ---- Q14m
R("Q14m: abundance proxies at the common 6.3x3.8\" beam: N(CH3OH)/N(H2) from dust, N(CS)/N(H2), N(CH3OH)/N(H13CN) limits, and the S/N contrast vs Tex",
"DUST N(H2) (q14j_h2.py; Band-6 258 GHz Xb4f and Band-7 346.5 GHz Xb47 continuum smoothed to 6.3x3.8\"; free-free/synchrotron removed by the 258/346 split with dust index 2+beta, beta 1.5-2, alpha_ff -0.4..-0.1, 7% flux calibration; kappa(346 GHz)=0.1(nu/1 THz)^beta = 0.02 cm2 per g gas, mu=2.8): S258/S346 mJy: N 19.8/45.3 (alpha 2.8, dust fraction 0.86), S 14.2/27.1 (2.19, 0.74), Bridge 14.7/31.9 (2.6, 0.82), W 13.8/26.5 (2.2, 0.74), lobe 6.8/11.0 (1.6, 0.61). N(H2) (1e21 cm-2; 16-84% for flux/beta/alpha_ff only) at Td 20/30/50 K: N 17.4/10.0/5.3, S 9.0/5.2/2.7, Bridge 11.8/6.8/3.6, W 8.8/5.0/2.7, lobe 3.1/1.7/0.9; the beam-averaged N(H2) is a factor ~3.3 (Td 20->50 K) uncertain and kappa is uncertain by ~2. N(CH3OH) (A+E) from the Xb4f whole-line amplitudes (N 0.147+-0.082, S 0.569+-0.090, Bridge 0.412+-0.085, W 0.604+-0.067, lobe 0.365+-0.106 K km/s): LTE (Tex 10/20/30 K) N: 2.7/4.0/5.9e13 (<7.2e13 3 sigma at 10 K), S 10.3/15.5/23.0e13, Bridge 7.5/11.2/16.7e13, W 11.0/16.4/24.4e13, lobe 6.6/9.9/14.8e13 cm-2; non-LTE (RADEX n 10^5.5-10^6.5, Tk 20-50 K) 1.7-4.9x the LTE-10K value: S 1.8-5.0e14. X(CH3OH)=N(CH3OH)/N(H2) at Td 30 K (LTE 10-30 K | non-LTE): N 2.7-6.0e-9 | 4.7e-9-1.3e-8 (1.8 sigma only), S 2.0-4.5e-8 | 3.5-9.7e-8, Bridge 1.1-2.5e-8 | 1.9-5.4e-8, W 2.2-4.8e-8 | 3.8-10.5e-8, lobe 3.8-8.5e-8 | 6.7-18.6e-8 (statistical +-16-30%; Td 20-50 K scales X by 0.57-1.9). S/N CONTRAST of X(CH3OH): MC median (16-84%) S/N = 7.7 (4.3-18.7) for equal Tex (any Tex) and Td 30 K; 5.2 (2.9-12) for Tex(N)=20 K, Tex(S)=10 K; 3.5 (1.9-8.3) for Tex(N)=30 K, Tex(S)=10 K; 1.9 (1.1-4.5) for Tex_N 30 K, Tex_S 10 K and Td_N 40 K, Td_S 25 K; 2.4 (1.3-5.7) for Td_N 50 K, Td_S 20 K with equal Tex: the S>N X(CH3OH) contrast is larger per H2 than per HCO+ (N has ~2x more dust) and survives sensible Tex differences (lower 5% >1.4 for Tex_N=30, Tex_S=10 K) but falls to ~2 (lower 5% 0.8-1.0) for opposite Td/Tex differences (T_N>T_S as in Q2); it rests on the N value being a 1.8 sigma measurement and on the 2.8-3.0 sigma S-N difference of Q14i (the MC probability of S>N is a statement about the fit errors, not the null test). N(CS) from CS 7-6 (Tex 20/30/50 K, Td 30 K): N 9.6/4.8/3.3e12 -> X(CS) 9.7/4.8/3.3e-10; S 3.5/1.8/1.2e12 -> 6.9/3.4/2.4e-10; Bridge 7.3/3.6/2.5e-10 (Tex 30: 3.6); W 5.2/2.6/1.8e-10; lobe 10/5.2/3.6e-10; N/S of X(CS) = 1.4 at any equal Tex (Tex-independent): CS differs by 1.4 between N and S per H2 while CH3OH differs by ~7.7: CH3OH, not CS, varies. H13CN: not detected (Q4 alpha(H13CN 4-3/HCN 4-3) 3 sigma < 0.105 N, <0.25 S (0.135 best model), <0.15 Bridge; CO 3-2 wing limited): N(H13CN) < 5.8-8.3e11 (N), 5.8-8.2e11 (S), 5.0-7.1e11 (Bridge) at Tex 20-100 K, hence N(CH3OH)/N(H13CN) > 32-102 (N), 127-400 (S), 105-333 (Bridge) (Tex CH3OH 10-30 K, Tex H13CN 20-100 K), i.e. N(CH3OH)/N(HCN) > 0.5-1.5 (N), 1.8-5.7 (S), 1.5-4.8 (Bridge) for 12C/13C=70 (assumed): lower limits only. Literature X values were not re-derived or compared here.",
"X(CH3OH): +-16-30% stat, x3.3 (Td 20-50 K), x2 (kappa), x1.7-4.9 (LTE vs RADEX), x3 (Tex 10-30 K); contrasts: see ranges","cm-2 / ratio","low",
"scripts/q14j_h2.py, q14n_summary.py -> out/q14e/h2_dust.csv, summary_X_CH3OH.csv, summary_XS_over_XN.csv, summary_X_CS.csv, summary_H13CN.csv","N, S, Bridge, Wclump, Soutflow",[A("dust","kappa_nu=0.1(nu/1 THz)^beta cm2/g gas (gas-to-dust 100 included), beta 1.5-2, Td 20-50 K, mu=2.8; dust fraction from the 258/346 GHz split with ff/synchrotron index -0.4..-0.1 (Harada 3 mm: -0.39 N, -0.37 S); continuum images assumed line-free"),A("H13CN","alpha limits from out/h13cn_limits.csv (Q4), applied to HCN 4-3 at 6.3x3.8\" (K km/s 7.30 N, 3.03 S, 4.39 Bridge); 12C/13C=70 assumed")])
# ---- Q14h summary
R("Q14h: summary: chemistry contrast between N, S, Bridge, S-outflow lobe and disk (what the data support)",
"(1) CH3OH is the only species with a region-dependent signal: extended (Xb4f flux rising to R=6\"), compact peaks at the Bridge/W clump (1.0-1.2 K km/s at 1.7\"), S-detected (4.6 sigma at 6.3x3.8\") and N barely (1.2-1.6 sigma): S>N CH3OH/HCO+ = 0.022-0.025 vs 0.005-0.006 (S-N 2.8-3.0 sigma per array: MODERATE, not firm; <1.5 sigma at <=4.45\"; the peaks sit 1-3\" from both nuclei towards the Bridge/W clump); lobe 0.016-0.027, disk undetected (<0.017). Per H2 (dust, Td 30 K) X(CH3OH) = 1e-8-1e-7 at S/Bridge/W/lobe and (3-13)e-9 at N; S/N of X = 7.7 (4-19) at equal Tex, 1.9-2.4 for opposite Td/Tex differences: contrast not robust to T_N>T_S. (2) CS: N(CS)/N(H2) differs only 1.4x N/S (CS 7-6/HCN 4-3 uniform, 1.1+-0.2); SO, SiS, HCN v2=1 undetected; SiO: 29SiO/30SiO undetected but the limits are 5-360x above Harada's SiO/CS (0.06): untestable at this depth. (3) Harada+2018: with the matched whole-line estimator our 254 line predicts Harada's 96.74/HCO+ at 1.7\" within ~1 sigma (pred/Harada 0.64-0.84 N,S in LTE at Harada's own Trot 11/17 K); the earlier 'x3 tension' was an estimator artefact; uv coverage, aperture/position and excitation are all allowed and none is required (Q14g). (4) CH3OH excitation: Tex(254) 5-7 K sub-thermal if n~1e5.5-1e6.5; N(CH3OH) 1.7-4.9x larger than LTE(10 K); Tk unconstrained. Ratios to HCO+ are not abundances: see Q14m for N(H2)- and H13CN-normalised proxies (all factor-3 uncertain).",
"see items","","low","out/q14*, out/q14e/*; scripts/q14a-q14p","N, S, Bridge, lobe, disk")
r['recipe'].append({"order":24,"stage":"modelling","description":"Q14 round 2: (1) q14e_lib/q14e_m0.py/q14g_ns.py: matched-aperture moment-0 with local baselines and empirical nulls (shifted windows, off-source ring); (2) q14h_deblend.py: HCO+-template deblend of CH3OH+SiS+30SiO (254 GHz) and CS+H2CS+29SiO (342.9 GHz); q14m_ns_deblend.py: S-N with whole-line amplitudes and ring null; (3) q14f_harada.py/q14l_harada_final.py: Harada Table 1-3,13 matched test (feathering, LTE at Harada Trot, RADEX posterior); q14o_aperture.py: native-resolution aperture flux recovery; (4) q14k_radex.py: RADEX E/A methanol grid (Tk 20-100, n 10^3.5-10^7, N 10^12.5-10^15.5); (5) q14i_abund.py/q14j_h2.py/q14n_summary.py/q14p_so.py: LTE columns, dust N(H2), abundance proxies, SiO/SO limits; build_report_q14b.py","inputs":"/data cubes and continuum, lit/harada/harada.txt, /opt/lamda"})
r['caveats'].append("Q14 round 2: (a) the matched Harada test uses a feather correction that assumes Xb4f complete and a smooth deficit; Xb4d/Xb4f array types are inferred from beams, not from visibilities; (b) S-N CH3OH is 2.8-3.0 sigma per array (moderate); both nuclei sit on the slope of Bridge/W-clump emission; (c) RADEX uses p-H2 collisions only and a 150 km/s FWHM, beam filling 1; Tex(254)~5-7 K and N(CH3OH) 1.7-4.9x LTE depend on n=1e5.5-1e6.5 inferred from one ratio at a 9.4x6.3\" beam; (d) dust N(H2) assumes kappa, Td 20-50 K and continuum free of line flux; (e) the 29SiO-H2CS blend is 29 km/s apart so 29SiO limits are a factor ~2.3 looser than the H2CS=0 fit; the SiO limits are 5-360x above Harada's SiO/CS, i.e. not a test.")
r['interpretation']=r['interpretation'].rstrip()+"\n\nQ14: Chemistry (third axis of the research question). The data show no shock-chemistry signature that separates the nuclei from each other in CS, SO, SiS, HCN v2=1; SiO is untestable (limits 5-360x above Harada's ratio). The one varying species is CH3OH: extended (still rising at R=6\"), peaked on the Bridge/W clump, detected at S (4.6 sigma at 6.3x3.8\") and weak at N (1.2-1.6 sigma); the S>N CH3OH/HCO+ contrast is moderate (2.8-3.0 sigma per array; <1.5 sigma at <=4.45\") and is not an S-nuclear source. Per H2 the contrast is ~8 at equal Tex but falls to ~2 if N is warmer/dustier-hot than S, as Q2 suggests, so it is not an established abundance difference. The comparison with Harada+2018 (largest SiO and CH3OH variation, S/N CH3OH ~4) is consistent for CH3OH: the Harada 96.74 data are 12-m-only Band 3 with MRS ~28\" and the matched whole-line estimator reproduces his S and N 96.74/HCO+ within ~1 sigma in LTE at his own Trot; the earlier apparent x3 tension was an estimator artefact. CH3OH is sub-thermally excited (Tex(254) 5-7 K for n~1e5.5-1e6.5): LTE column densities are lower limits by 1.7-4.9x. Earlier p0001 claims (Trot 9 K, Q-branch excess, Band-5 Bridge enhancement) remain withdrawn as baseline-limited."
